INSERT OR IGNORE INTO places(id,name,en,cat,area,address,lat,lng,tags,description,story,hours,phone,image,status,created_at,updated_at) VALUES('afa','測試阿發修鞋店','A Fa Shoe Repair','修','澳門半島','亞婆井前地 12 號',22.1924,113.5395,'["減廢", "社區", "文化"]','修補的不只是鞋，也是對物件的尊重。','在這裡，每一雙鞋都有故事。阿發師傅把磨損的鞋底重新縫好，也讓熟悉的步伐繼續走過這座城市。','10:00 – 19:00（週一休息）','+853 6288 1234','assets/shoe-repair.png','published','2026-09-21T00:00:00.000Z','2026-09-21T00:00:00.000Z');
INSERT OR IGNORE INTO places(id,name,en,cat,area,address,lat,lng,tags,description,story,hours,phone,image,status,created_at,updated_at) VALUES('market','測試下環街市','Barra Market','食','澳門半島','李加祿街',22.1882,113.5363,'["食物", "社區"]','在街坊的招呼聲裡，認識食物從哪裡來。','從當季蔬菜到一家人的晚餐，街市是城市最親密的食物地圖。','07:00 – 19:00','','assets/macau-waterfront.png','published','2026-09-21T00:00:00.000Z','2026-09-21T00:00:00.000Z');
INSERT OR IGNORE INTO places(id,name,en,cat,area,address,lat,lng,tags,description,story,hours,phone,image,status,created_at,updated_at) VALUES('reuse','測試再生工房','Reuse Workshop','修','路環','路環蓮花海濱大馬路 88 號',22.1172,113.5591,'["重用", "社區"]','修復、重用，讓好物再出發。','帶一件需要照顧的舊物來，和街坊一起找回它的下一段旅程。','11:00 – 18:00','','assets/shoe-repair.png','published','2026-09-21T00:00:00.000Z','2026-09-21T00:00:00.000Z');
INSERT OR IGNORE INTO places(id,name,en,cat,area,address,lat,lng,tags,description,story,hours,phone,image,status,created_at,updated_at) VALUES('garden','測試望廈社區農圃','Mong Ha Garden','去','澳門半島','望廈山公園旁',22.2112,113.5462,'["食物", "自然與生物多樣性", "社區"]','在城裡留一小塊土，種出新的相遇。','居民一起播種、澆水、分享收成，也分享彼此的生活。','全日開放','','assets/macau-waterfront.png','published','2026-09-21T00:00:00.000Z','2026-09-21T00:00:00.000Z');
INSERT OR IGNORE INTO places(id,name,en,cat,area,address,lat,lng,tags,description,story,hours,phone,image,status,created_at,updated_at) VALUES('bookshop','測試邊度書店','Where Bookshop','學','澳門半島','瘋堂斜巷 25 號',22.1985,113.5494,'["文化", "社區"]','從一本書開始，打開地方的想像。','小書店收藏城市的提問，也為關心地方的人留下一張椅子。','12:00 – 19:00','','assets/macau-waterfront.png','published','2026-09-21T00:00:00.000Z','2026-09-21T00:00:00.000Z');
INSERT OR IGNORE INTO places(id,name,en,cat,area,address,lat,lng,tags,description,story,hours,phone,image,status,created_at,updated_at) VALUES('coast','測試龍環葡韻濕地步道','Taipa Wetland Walk','去','氹仔','龍環葡韻旁',22.1535,113.5592,'["水", "自然與生物多樣性"]','慢慢走，聽見濕地與城市一起呼吸。','在木棧道上放慢腳步，觀察水鳥、植物和潮汐留下的線索。','全日開放','','assets/macau-waterfront.png','published','2026-09-21T00:00:00.000Z','2026-09-21T00:00:00.000Z');
INSERT OR IGNORE INTO places(id,name,en,cat,area,address,lat,lng,tags,description,story,hours,phone,image,status,created_at,updated_at) VALUES('repairbike','測試阿明單車維修','Ming Bicycle Repair','修','澳門半島','筷子基龍街 5 號',22.2065,113.5337,'["減廢", "交通"]','讓車輪繼續轉，也讓城市更宜居。','一輛單車、一雙熟手，讓低碳的選擇更容易成為日常。','10:30 – 18:30','','assets/shoe-repair.png','published','2026-09-21T00:00:00.000Z','2026-09-21T00:00:00.000Z');
INSERT OR IGNORE INTO places(id,name,en,cat,area,address,lat,lng,tags,description,story,hours,phone,image,status,created_at,updated_at) VALUES('shop','測試綠意雜貨','Green Living Store','買','氹仔','官也街 36 號',22.1527,113.5552,'["減廢", "食物"]','把自備容器與少一點包裝，帶進每天的採買。','一間小店，讓可重用和本地選擇變得自然。','11:00 – 20:00','','assets/macau-waterfront.png','published','2026-09-21T00:00:00.000Z','2026-09-21T00:00:00.000Z');
